class SSEResponse(StreamingResponse):
    """
    Server-Sent Events response.
    """
    def __init__(self, content: Any, media_type: str = "text/event-stream", **overrides: Any):
        headers = {
            "Content-Type": media_type,
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
        }
        # Merge custom overrides with required SSE headers
        final_headers = {**headers, **overrides}
        super().__init__(content, headers=final_headers, **overrides)

